%[text] # Draft by interp1 and fzero: model written once
R = 0.213;
L = 5;
m = 200;
rho = 1000;
dd = 0:0.001:2*R;
displaced = @(d) 2*rho*L*(R^2*acos(1 - d/R) - (R - d).*sqrt(R^2 - (R - d).^2));
%%
%[text] ## interp1
d_interp = interp1(displaced(dd), dd, m) %[output:23d4b890]
%%
%[text] ## fzero
d_fzero = fzero(@(d) displaced(d) - m, R)
%%
%[text] ## Check
plot(dd, displaced(dd) - m) %[output:93c9fae5]
grid on %[output:93c9fae5]

